import { Router, Request, Response } from 'express';
import axios from 'axios';
import { generateRandomString, verifyState } from './security';

const router = Router();
const CLIENT_ID = process.env.CLIENT_ID;
const CLIENT_SECRET = process.env.CLIENT_SECRET;
const REDIRECT_URI = process.env.REDIRECT_URI;
const TOKEN_URL = process.env.TOKEN_URL;

router.get('/callback', async (req: Request, res: Response) => {
  const { code, state } = req.query;
  const storedState = req.session.oauthState;

  // Verify CSRF state parameter
  if (!verifyState(state as string, storedState)) {
    return res.status(400).send('Invalid state parameter');
  }

  // Verify authorization code exists
  if (!code) {
    return res.status(400).send('Missing authorization code');
  }

  try {
    // Exchange code for tokens — this happens server-side so the
    // token never touches the browser
    const params = new URLSearchParams();
    params.append('grant_type', 'authorization_code');
    params.append('code', code as string);
    params.append('client_id', CLIENT_ID);
    params.append('client_secret', CLIENT_SECRET);
    params.append('redirect_uri', REDIRECT_URI);

    const response = await axios.post(TOKEN_URL, params, {
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    });

    const { access_token, refresh_token, id_token, expires_in } = response.data;

    // Store tokens securely in session (or a server-side store)
    req.session.accessToken = access_token;
    req.session.refreshToken = refresh_token;
    req.session.idToken = id_token;
    req.session.expiresAt = Date.now() + expires_in * 1000;

    // Clear the state to prevent reuse
    delete req.session.oauthState;

    res.redirect('/dashboard');
  } catch (error: any) {
    console.error('Token exchange failed:', error.response?.data || error.message);
    res.status(500).send('Authentication failed');
  }
});

const AUTHORIZATION_URL = 'https://auth.example.com/authorize';
const CLIENT_ID = 'your-client-id';
const REDIRECT_URI = 'https://your-app.com/auth/callback';
const SCOPES = 'openid profile email api.read';

function login() {
  // Generate a cryptographically random state value
  // In production, use crypto.getRandomValues
  const state = btoa(Math.random().toString(36).substring(2));

  // Generate a nonce to bind the id_token
  const nonce = btoa(Math.random().toString(36).substring(2));

  // Store state and nonce in session storage for verification
  sessionStorage.setItem('oauth_state', state);
  sessionStorage.setItem('oauth_nonce', nonce);

  // Build the authorization URL with all required parameters
  const params = new URLSearchParams({
    client_id: CLIENT_ID,
    redirect_uri: REDIRECT_URI,
    response_type: 'code',
    scope: SCOPES,
    state: state,
    nonce: nonce,
  });

  // Redirect the browser to the authorization server
  window.location.href = `${AUTHORIZATION_URL}?${params.toString()}`;
}

document.getElementById('login-btn').addEventListener('click', login);

